def edit_distance(a: str, b: str) -> int:
    """Compute the typo-tolerant edit distance between two strings.

    Uses the Damerau-Levenshtein distance: the minimum number of
    single-character insertions, deletions, substitutions, or
    transpositions of two adjacent characters needed to transform
    ``a`` into ``b``. A single adjacent transposition costs 1.
    """
    la, lb = len(a), len(b)
    if la == 0:
        return lb
    if lb == 0:
        return la

    # dp[i][j] = distance between a[:i] and b[:j]
    dp = [[0] * (lb + 1) for _ in range(la + 1)]
    for i in range(la + 1):
        dp[i][0] = i
    for j in range(lb + 1):
        dp[0][j] = j

    # last occurrence of each character in a and b
    max_char = 256
    da = {}

    for i in range(1, la + 1):
        db = {}
        for j in range(1, lb + 1):
            cost = 0 if a[i - 1] == b[j - 1] else 1
            j1 = db.get(a[i - 1], 0)
            i1 = da.get(b[j - 1], 0)
            dp[i][j] = min(
                dp[i - 1][j] + 1,        # deletion
                dp[i][j - 1] + 1,        # insertion
                dp[i - 1][j - 1] + cost,  # substitution
            )
            if j1 > 0 and i1 > 0:
                dp[i][j] = min(
                    dp[i][j],
                    dp[i1][j1] + (i - i1 - 1) + 1 + (j - j1 - 1),
                )
        db[b[j - 1]] = j
